def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def is_palindrome(s):
    cleaned = ''.join(char.lower() for char in s if char.isalnum())
    return cleaned == cleaned[::-1]

import re

def word_count(text):
    # Extract all words (maximal runs of letters, digits, or apostrophes)
    words = re.findall(r"[a-zA-Z0-9']+", text)

    # Count occurrences (case-insensitive)
    word_counts = {}
    for word in words:
        word_lower = word.lower()
        word_counts[word_lower] = word_counts.get(word_lower, 0) + 1

    return word_counts

import re
from collections import Counter

def word_count(text: str) -> dict:
    words = re.findall(r"[a-z0-9']+", text.lower())
    return dict(Counter(words))

def flatten(items):
    result = []
    for item in items:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

from itertools import chain

def flatten(items):
    def flatten_recursive(items):
        if isinstance(items, list):
            return chain.from_iterable(flatten_recursive(item) for item in items)
        else:
            return items

    return list(flatten_recursive(items))

def roman_to_int(s: str) -> int:
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_val = 0
    for char in reversed(s):
        curr_val = roman_map[char]
        if curr_val < prev_val:
            total -= curr_val
        else:
            total += curr_val
        prev_val = curr_val
    return total

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or touching, merge them
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            # No overlap, append as new interval
            merged.append(current)

    return merged

def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return (seen[complement], i)
        seen[num] = i
    return None

def caesar(text, shift):
    result = []
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            shifted = (ord(char) - base + shift) % 26
            result.append(chr(base + shifted))
        else:
            result.append(char)
    return "".join(result)

def is_balanced(s):
    """
    Check if all brackets in the string are properly balanced.

    Args:
        s (str): Input string containing characters and brackets

    Returns:
        bool: True if brackets are balanced, False otherwise
    """
    brackets = {'(': ')', '[': ']', '{': '}'}
    stack = []

    for char in s:
        if char in brackets:
            stack.append(char)
        elif char in brackets.values():
            if not stack or stack[-1] != brackets.get(char):
                return False
            stack.pop()

    return len(stack) == 0

def is_balanced(s):
    bracket_map = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack.pop() != bracket_map[char]:
                return False
    return len(stack) == 0

def rle_encode(s):
    if not s:
        return ''

    result = []
    count = 1

    for i in range(1, len(s)):
        current_char = s[i-1]
        next_char = s[i]
        if next_char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            count = 1

    # Append the last run
    result.append(f"{s[-1]}{count}")

    return "".join(result)

from itertools import groupby

def rle_encode(s):
    if not s:
        return ''
    return ''.join(char + str(len(list(group))) for char, group in groupby(s))
